const rowsOf = (node) => { try { return $(node).all().map((i) => i.json).filter((r) => r && Object.keys(r).length); } catch (e) { return []; } };
const activeClients = () => rowsOf('Read Clients').filter((c) => c.client_id && String(c.status || '').toLowerCase() === 'active');
const ymd = (d) => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
const daysAgo = (s) => { const t = Date.parse(s); return Number.isNaN(t) ? null : Math.floor((Date.now() - t) / 864e5); };

const now = new Date();
const cur = { startDate: ymd(new Date(now.getFullYear(), now.getMonth() - 1, 1)), endDate: ymd(new Date(now.getFullYear(), now.getMonth(), 0)), name: 'current' };
const prev = { startDate: ymd(new Date(now.getFullYear(), now.getMonth() - 2, 1)), endDate: ymd(new Date(now.getFullYear(), now.getMonth() - 1, 0)), name: 'previous' };
const m = (...names) => names.map((name) => ({ name }));
return activeClients().filter((c) => String(c.ga4_property_id || '').replace(/\D/g, '')).map((c) => ({ json: {
  client: c, month: cur.startDate.slice(0, 7), ga4_property_id: c.ga4_property_id,
  ga4_request: { requests: [
    { dateRanges: [cur, prev], metrics: m('sessions', 'totalUsers', 'newUsers', 'keyEvents', 'totalRevenue', 'engagementRate') },
    { dateRanges: [cur, prev], dimensions: m('sessionDefaultChannelGroup'), metrics: m('sessions', 'keyEvents', 'totalRevenue'), limit: 12 },
    { dateRanges: [cur], dimensions: m('landingPagePlusQueryString'), metrics: m('sessions', 'keyEvents', 'engagementRate'), orderBys: [{ metric: { metricName: 'sessions' }, desc: true }], limit: 10 },
  ] },
} }));

const src = $('Prep GA4 Requests').item.json;
const c = src.client;
const toRows = (r) => (r?.rows || []).map((row) => {
  const o = {};
  (r.dimensionHeaders || []).forEach((h, i) => { o[h.name] = row.dimensionValues[i].value; });
  (r.metricHeaders || []).forEach((h, i) => { o[h.name] = Number(row.metricValues[i].value); });
  return o;
});
const [tot, ch, lp] = ($json.reports || []).map(toRows);
const cur = (tot || []).find((r) => r.dateRange === 'current') || {};
const prev = (tot || []).find((r) => r.dateRange === 'previous') || {};
const mom = (a, b) => (b ? ((a - b) / b) * 100 : null);
const k = (name) => ({ current: cur[name] ?? 0, previous: prev[name] ?? 0, mom_pct: mom(cur[name] ?? 0, prev[name] ?? 0) });
const kpis = { sessions: k('sessions'), users: k('totalUsers'), new_users: k('newUsers'), key_events: k('keyEvents'), revenue: k('totalRevenue'), engagement_rate: k('engagementRate') };
const channels = {};
for (const r of ch || []) { const n = r.sessionDefaultChannelGroup; (channels[n] ||= {})[r.dateRange] = { sessions: r.sessions, key_events: r.keyEvents, revenue: r.totalRevenue }; }
const channel_table = Object.entries(channels).map(([name, v]) => ({ channel: name, sessions: v.current?.sessions || 0, sessions_mom_pct: mom(v.current?.sessions || 0, v.previous?.sessions || 0), key_events: v.current?.key_events || 0 }))
  .sort((a, b) => b.sessions - a.sessions);
const top_pages = (lp || []).map((r) => ({ page: r.landingPagePlusQueryString, sessions: r.sessions, key_events: r.keyEvents, engagement_rate: r.engagementRate }));
const ga4_error = $json.error ? ($json.error.message || JSON.stringify($json.error)) : (!tot?.length ? 'GA4 returned no data' : null);

const schema = { type: 'object', additionalProperties: false,
  required: ['headline', 'summary', 'wins', 'concerns', 'insights', 'next_month_experiments', 'client_note'],
  properties: { headline: { type: 'string', description: 'One line, under 90 characters' }, summary: { type: 'string' },
    wins: { type: 'array', items: { type: 'string' } }, concerns: { type: 'array', items: { type: 'string' } },
    insights: { type: 'array', items: { type: 'object', additionalProperties: false, required: ['observation', 'so_what'], properties: { observation: { type: 'string' }, so_what: { type: 'string' } } } },
    next_month_experiments: { type: 'array', items: { type: 'object', additionalProperties: false, required: ['name', 'hypothesis', 'success_metric'], properties: { name: { type: 'string' }, hypothesis: { type: 'string' }, success_metric: { type: 'string' } } } },
    client_note: { type: 'string', description: 'A warm 2-3 sentence note from the account manager' } } };
return { json: { client: c, month: src.month, kpis, channel_table, top_pages, ga4_error, brain: {
  skill: 'analytics', caller: 'Performance Pulse', client: c.client_name, effort: 'high', max_tokens: 10000, schema,
  context: { client: c.client_name, goals: c.goals, services: c.services, month: src.month, kpis, channels: channel_table, top_landing_pages: top_pages, data_issue: ga4_error },
  task: 'Write the monthly performance story for this client. Use only these numbers and never invent data. Explain the why behind the biggest movements using the channel and landing-page data, tie everything to their goals, and flag tracking problems if the data looks broken. Propose exactly 3 experiments for next month.',
} } };

const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const li = (arr) => (arr || []).map((t) => `<li style="margin:0 0 6px">${esc(t)}</li>`).join('');
const card = (title, inner) => `<div style="border:1px solid #e5e7eb;border-radius:10px;padding:18px 20px;margin:0 0 16px"><h3 style="margin:0 0 10px;font-size:16px;color:#111827">${esc(title)}</h3>${inner}</div>`;
const shell = (title, sub, inner) => `<div style="font-family:-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;max-width:680px;margin:0 auto;color:#1f2937;line-height:1.5"><div style="padding:24px 0 8px"><div style="font-size:12px;letter-spacing:.08em;text-transform:uppercase;color:#6b7280">${esc(sub)}</div><h1 style="margin:4px 0 0;font-size:24px;color:#111827">${esc(title)}</h1></div>${inner}</div>`;
const pct = (v) => (v === null || v === undefined || Number.isNaN(v)) ? 'n/a' : `${v > 0 ? '+' : ''}${v.toFixed(1)}%`;

const x = $json; const a = x.ai || {}; const c = x.client; const k = x.kpis;
const cfg = $('Config').first().json;
const fmt = (n, money) => money ? '$' + Math.round(n).toLocaleString() : Math.round(n).toLocaleString();
const tile = (label, v, money, rate) => `<td style="padding:12px;border:1px solid #e5e7eb;border-radius:8px;text-align:center;width:25%"><div style="font-size:12px;color:#6b7280">${label}</div><div style="font-size:22px;font-weight:700;color:#111827">${rate ? (v.current * 100).toFixed(1) + '%' : fmt(v.current, money)}</div><div style="font-size:12px;color:${(v.mom_pct ?? 0) >= 0 ? '#059669' : '#dc2626'}">${pct(v.mom_pct)} MoM</div></td>`;
const chRows = x.channel_table.slice(0, 8).map((r) => `<tr><td style="padding:6px 8px;border-bottom:1px solid #f3f4f6">${esc(r.channel)}</td><td style="padding:6px 8px;border-bottom:1px solid #f3f4f6;text-align:right">${fmt(r.sessions)}</td><td style="padding:6px 8px;border-bottom:1px solid #f3f4f6;text-align:right">${pct(r.sessions_mom_pct)}</td><td style="padding:6px 8px;border-bottom:1px solid #f3f4f6;text-align:right">${fmt(r.key_events)}</td></tr>`).join('');
const insights = (a.insights || []).map((i) => `<li style="margin:0 0 8px"><b>${esc(i.observation)}</b><br>${esc(i.so_what)}</li>`).join('');
const exps = (a.next_month_experiments || []).map((e) => `<li style="margin:0 0 8px"><b>${esc(e.name)}</b>: ${esc(e.hypothesis)} <span style="color:#6b7280">(success = ${esc(e.success_metric)})</span></li>`).join('');
const html = shell(a.headline || `${c.client_name}: ${x.month} performance`, `${cfg.agency_name} · monthly report · ${x.month}`,
  `<p>${esc(a.client_note || '')}</p>`
  + `<table style="border-spacing:8px;margin:0 -8px 16px;width:100%"><tr>${tile('Sessions', k.sessions)}${tile('Key events', k.key_events)}${tile('Revenue', k.revenue, true)}${tile('Engagement', k.engagement_rate, false, true)}</tr></table>`
  + card('Summary', `<p style="margin:0">${esc(a.summary || x.ai_error || x.ga4_error || '')}</p>`)
  + card('Wins', `<ul style="padding-left:18px;margin:0">${li(a.wins)}</ul>`)
  + card('Watch-outs', `<ul style="padding-left:18px;margin:0">${li(a.concerns)}</ul>`)
  + card('What it means', `<ul style="padding-left:18px;margin:0">${insights}</ul>`)
  + card('Channel mix', `<table style="width:100%;border-collapse:collapse;font-size:13px"><tr style="color:#6b7280;text-align:left"><th style="padding:6px 8px">Channel</th><th style="padding:6px 8px;text-align:right">Sessions</th><th style="padding:6px 8px;text-align:right">MoM</th><th style="padding:6px 8px;text-align:right">Key events</th></tr>${chRows}</table>`)
  + card('Next month we will test', `<ol style="padding-left:18px;margin:0">${exps}</ol>`));
return { json: { ...x, subject: `${c.client_name} · ${x.month} report: ${a.headline || 'monthly performance'}`.slice(0, 180), html } };

const x = $('Render Report').item.json; const k = x.kpis; const r1 = (v) => (v === null || v === undefined ? '' : Number(v.toFixed(1)));
return { json: { month: x.month, client_id: x.client.client_id, client_name: x.client.client_name, sessions: k.sessions.current, users: k.users.current,
  key_events: k.key_events.current, revenue: Number(k.revenue.current.toFixed(2)), engagement_rate: Number(k.engagement_rate.current.toFixed(4)),
  sessions_mom_pct: r1(k.sessions.mom_pct), key_events_mom_pct: r1(k.key_events.mom_pct), revenue_mom_pct: r1(k.revenue.mom_pct),
  headline: x.ai?.headline || x.ga4_error || '' } };
